    84  static size_t encode_varint(uint8_t *buf, size_t value) {
    85    size_t len = 0;
    86
    87    do {
    88      uint8_t b = (uint8_t) (value % 128);
    89      value /= 128;
    90      if (value > 0) b |= 0x80;
    91      buf[len++] = b;
    92    } while (value > 0);
    93
    94    return len;
    95  }
