    97  static size_t decode_varint(const uint8_t *buf, size_t len, size_t *value) {
    98    size_t multiplier = 1, offset;
    99    *value = 0;
   100
   101    for (offset = 0; offset < 4 && offset < len; offset++) {
   102      uint8_t encoded_byte = buf[offset];
   103      *value += (encoded_byte & 0x7f) * multiplier;
   104      multiplier *= 128;
   105
   106      if ((encoded_byte & 0x80) == 0) return offset + 1;
   107    }
   108
   109    return 0;
   110  }
