   122  static size_t get_properties_length(struct mg_mqtt_prop *props, size_t count) {
   123    size_t i, size = 0;
   124    for (i = 0; i < count; i++) {
   125      size++;  // identifier
   126      switch (mqtt_prop_type_by_id(props[i].id)) {
   127        case MQTT_PROP_TYPE_STRING_PAIR:
   128          size += (uint32_t) (props[i].val.len + props[i].key.len +
   129                              2 * sizeof(uint16_t));
   130          break;
   131        case MQTT_PROP_TYPE_STRING:
   132          size += (uint32_t) (props[i].val.len + sizeof(uint16_t));
   133          break;
   134        case MQTT_PROP_TYPE_BINARY_DATA:
   135          size += (uint32_t) (props[i].val.len + sizeof(uint16_t));
   136          break;
   137        case MQTT_PROP_TYPE_VARIABLE_INT:
   138          size += varint_size((uint32_t) props[i].iv);
   139          break;
   140        case MQTT_PROP_TYPE_INT: size += (uint32_t) sizeof(uint32_t); break;
   141        case MQTT_PROP_TYPE_SHORT: size += (uint32_t) sizeof(uint16_t); break;
   142        case MQTT_PROP_TYPE_BYTE: size += (uint32_t) sizeof(uint8_t); break;
   143        default: return size;  // cannot parse further down
   144      }
   145    }
   146
   147    return size;
   148  }
