   269  void mg_mqtt_login(struct mg_connection *c, const struct mg_mqtt_opts *opts) {
   270    char client_id[21];
   271    struct mg_str cid = opts->client_id;
   272    size_t total_len = 7 + 1 + 2 + 2;
   273    uint8_t hdr[8] = {0, 4, 'M', 'Q', 'T', 'T', 0, 0};
   274    hdr[6] = opts->version;
   275
   276    if (cid.len == 0) {
   277      mg_random_str(client_id, sizeof(client_id) - 1);
   278      client_id[sizeof(client_id) - 1] = '\0';
   279      cid = mg_str(client_id);
   280    }
   281
   282    if (hdr[6] == 0) hdr[6] = 4;  // If version is not set, use 4 (3.1.1)
   283    c->is_mqtt5 = hdr[6] == 5;    // Set version 5 flag
   284    hdr[7] = (uint8_t) ((opts->qos & 3) << 3);  // Connection flags
   285    if (opts->user.len > 0) {
   286      total_len += 2 + (uint32_t) opts->user.len;
   287      hdr[7] |= MQTT_HAS_USER_NAME;
   288    }
   289    if (opts->pass.len > 0) {
   290      total_len += 2 + (uint32_t) opts->pass.len;
   291      hdr[7] |= MQTT_HAS_PASSWORD;
   292    }
   293    if (opts->topic.len > 0) {  // allow zero-length msgs, message.len is size_t
   294      total_len += 4 + (uint32_t) opts->topic.len + (uint32_t) opts->message.len;
   295      hdr[7] |= MQTT_HAS_WILL;
   296    }
   297    if (opts->clean || cid.len == 0) hdr[7] |= MQTT_CLEAN_SESSION;
   298    if (opts->retain) hdr[7] |= MQTT_WILL_RETAIN;
   299    total_len += (uint32_t) cid.len;
   300    if (c->is_mqtt5) {
   301      total_len += get_props_size(opts->props, opts->num_props);
   302      if (hdr[7] & MQTT_HAS_WILL)
   303        total_len += get_props_size(opts->will_props, opts->num_will_props);
   304    }
   305
   306    // keepalive == 0 means "do not disconnect us!"
   307    if (!mqtt_send_header(c, MQTT_CMD_CONNECT, 0, (uint32_t) total_len) ||
   308        !mg_send(c, hdr, sizeof(hdr)) ||
   309        !mg_send_u16(c, mg_htons((uint16_t) opts->keepalive)))
   310      goto fail;
   311
   312    if (c->is_mqtt5 && !mg_send_mqtt_properties(c, opts->props, opts->num_props))
   313      goto fail;
   314
   315    if (!mg_send_u16(c, mg_htons((uint16_t) cid.len)) ||
   316        !mg_send(c, cid.buf, cid.len))
   317      goto fail;
   318
   319    if (hdr[7] & MQTT_HAS_WILL) {
   320      if (c->is_mqtt5 &&
   321          !mg_send_mqtt_properties(c, opts->will_props, opts->num_will_props))
   322        goto fail;
   323
   324      if (!mg_send_u16(c, mg_htons((uint16_t) opts->topic.len)) ||
   325          !mg_send(c, opts->topic.buf, opts->topic.len) ||
   326          !mg_send_u16(c, mg_htons((uint16_t) opts->message.len)) ||
   327          !mg_send(c, opts->message.buf, opts->message.len))
   328        goto fail;
   329    }
   330    if (opts->user.len > 0 &&
